async function loadUserInfo(callerUid, uids) {
	async function getIPs() {
		return await Promise.all(uids.map(uid => db.getSortedSetRevRange(`uid:${uid}:ip`, 0, -1)));
	}
	const [isAdmin, userData, lastonline, ips] = await Promise.all([
		user.isAdministrator(uids),
		user.getUsersWithFields(uids, userFields, callerUid),
		db.sortedSetScores('users:online', uids),
		getIPs(),
	]);
	userData.forEach((user, index) => {
		if (user) {
			user.administrator = isAdmin[index];
			user.flags = userData[index].flags || 0;
			const timestamp = lastonline[index] || user.joindate;
			user.lastonline = timestamp;
			user.lastonlineISO = utils.toISOString(timestamp);
			user.ips = ips[index];
			user.ip = ips[index] && ips[index][0] ? ips[index][0] : null;
		}
	});
	await Promise.all(userData.map(async (userDataItem) => {
		if (!userDataItem) {
			return;
		}

		const profileEmail = userDataItem.email;
		const validationEmail = await user.email.getEmailForValidation(userDataItem.uid);
		if (!userDataItem.email) {
			userDataItem.email = validationEmail || '';
		}

		const hasEmail = !!(profileEmail || validationEmail);
		const validated = !!profileEmail && parseInt(userDataItem['email:confirmed'], 10) === 1;
		const pending = hasEmail && !validated && await user.email.isValidationPending(userDataItem.uid, validationEmail || profileEmail);
		userDataItem.emailStatusValidated = validated;
		userDataItem.emailStatusPending = pending;
		userDataItem.emailStatusExpired = hasEmail && !validated && !pending;
		userDataItem.emailStatusMissing = !hasEmail;
	}));
	return userData;
}

