   163	async function loadUserInfo(callerUid, uids) {
   164		async function getIPs() {
   165			return await Promise.all(uids.map(uid => db.getSortedSetRevRange(`uid:${uid}:ip`, 0, -1)));
   166		}
   167		const [isAdmin, userData, lastonline, ips] = await Promise.all([
   168			user.isAdministrator(uids),
   169			user.getUsersWithFields(uids, userFields, callerUid),
   170			db.sortedSetScores('users:online', uids),
   171			getIPs(),
   172		]);
   173		userData.forEach((user, index) => {
   174			if (user) {
   175				user.administrator = isAdmin[index];
   176				user.flags = userData[index].flags || 0;
   177				const timestamp = lastonline[index] || user.joindate;
   178				user.lastonline = timestamp;
   179				user.lastonlineISO = utils.toISOString(timestamp);
   180				user.ips = ips[index];
   181				user.ip = ips[index] && ips[index][0] ? ips[index][0] : null;
   182			}
   183		});
   184		await Promise.all(userData.map(async (userDataItem) => {
   185			if (!userDataItem) {
   186				return;
   187			}
   188	
   189			const profileEmail = userDataItem.email;
   190			const validationEmail = await user.email.getEmailForValidation(userDataItem.uid);
   191			if (!userDataItem.email) {
   192				userDataItem.email = validationEmail || '';
   193			}
   194	
   195			const hasEmail = !!(profileEmail || validationEmail);
   196			const validated = !!profileEmail && parseInt(userDataItem['email:confirmed'], 10) === 1;
   197			const pending = hasEmail && !validated && await user.email.isValidationPending(userDataItem.uid);
   198			userDataItem.emailStatusValidated = validated;
   199			userDataItem.emailStatusPending = pending;
   200			userDataItem.emailStatusExpired = hasEmail && !validated && !pending;
   201			userDataItem.emailStatusMissing = !hasEmail;
   202		}));
   203		return userData;
   204	}
